import ctypes
import os

class GSLFunction:
    def __init__(self, func):
        self.func = func
        self.f = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.c_void_p)(self._wrap_func)

    def _wrap_func(self, x, params):
        return self.func(x)

    def get_gsl_function(self):
        return self.f

class CQuadWorkspace:
    def __init__(self, workspace_size):
        self.gsl = ctypes.CDLL(os.environ.get("GSL_LIB", "/usr/local/gsl/lib/libgsl.so"))
        self.workspace = self.gsl.gsl_integration_cquad_workspace_alloc(workspace_size)

    def __del__(self):
        if hasattr(self, "gsl") and hasattr(self, "workspace"):
            self.gsl.gsl_integration_cquad_workspace_free(self.workspace)

def integrate_function(func, a, b, epsabs, epsrel, workspace_size):
    try:
        ctypes.CDLL(os.environ.get("GSL_CBLAS_LIB", "/usr/local/gsl/lib/libgslcblas.so"), mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL(os.environ.get("GSL_LIB", "/usr/local/gsl/lib/libgsl.so"))
    except OSError as e:
        raise OSError("Could not load GSL libraries. Please check your GSL installation and environment variables.") from e

    gsl_function = GSLFunction(func)
    workspace = CQuadWorkspace(workspace_size)

    result = ctypes.c_double()
    abserr = ctypes.c_double()
    nevals = ctypes.c_size_t()

    status = gsl.gsl_integration_cquad(
        gsl_function.get_gsl_function(),
        a, b,
        epsabs, epsrel,
        workspace.workspace,
        ctypes.byref(result),
        ctypes.byref(abserr),
        ctypes.byref(nevals),
    )

    if status != 0:
        raise RuntimeError(f"GSL integration failed with status code: {status}")

    return result.value, abserr.value, nevals.value

