import ctypes
import os

try:
    # Define the path to the shared libraries
    libgslcblas_path = "/usr/local/gsl/lib/libgslcblas.so"
    libgsl_path = "/usr/local/gsl/lib/libgsl.so"

    # Load the GSL libraries in the correct order
    if os.path.exists(libgslcblas_path):
        ctypes.CDLL(libgslcblas_path, mode=ctypes.RTLD_GLOBAL)
    if os.path.exists(libgsl_path):
        gsl = ctypes.CDLL(libgsl_path)

    class GSLVector:
        def __init__(self, size):
            self.size = size
            self.data = (ctypes.c_double * size)()  # Initialize with zeros
            self.p = gsl.gsl_vector_alloc(size)

        def __del__(self):
            gsl.gsl_vector_free(self.p)

        def from_list(self, lst):
            if len(lst) != self.size:
                raise ValueError("List size must match vector size.")
            for i, val in enumerate(lst):
                self.data[i] = val
            gsl.gsl_vector_view_array(self.p, self.data, self.size)

        def to_list(self):
            return [self.p[i] for i in range(self.size)]

    def vector_add(a, b):
        if not isinstance(a, GSLVector) or not isinstance(b, GSLVector):
            raise TypeError("Inputs must be GSLVector objects.")
        if a.size != b.size:
            raise ValueError("Vectors must have the same size.")

        result = GSLVector(a.size)
        gsl.gsl_vector_add(result.p, a.p, b.p)
        return result.to_list()

except OSError as e:
    print(f"Error loading GSL libraries: {e}")
except Exception as e:
    print(f"An unexpected error occurred: {e}")

