    _fields_ = [("val", ctypes.c_double), ("err", ctypes.c_double), ("e10", ctypes.c_int)]

def smash_result(input_dict):
    try:
        # Load GSL libraries in the correct order
        libgslcblas_path = os.path.join(os.sep, 'usr', 'local', 'gsl', 'lib', 'libgslcblas.so')
        libgsl_path = os.path.join(os.sep, 'usr', 'local', 'gsl', 'lib', 'libgsl.so')        
        if os.path.exists(libgslcblas_path):
            ctypes.CDLL(libgslcblas_path, mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL(libgsl_path) if os.path.exists(libgsl_path) else None
        if gsl is None:
            raise OSError("libgsl.so not found. Please install GSL and set LD_LIBRARY_PATH.")

        # Prepare input and output structures
        input_struct = gsl_sf_result_e10(ctypes.c_double(input_dict['val']), ctypes.c_double(input_dict['err']), ctypes.c_int(input_dict['e10']))
        output_struct = gsl_sf_result()

        # Call the GSL function
        gsl.gsl_sf_result_smash_e.argtypes = [ctypes.POINTER(gsl_sf_result_e10), ctypes.POINTER(gsl_sf_result)]
        gsl.gsl_sf_result_smash_e.restype = ctypes.c_int
        status = gsl.gsl_sf_result_smash_e(ctypes.byref(input_struct), ctypes.byref(output_struct))

