class gsl_matrix_complex:
    def __init__(self, size1, size2):
        self._ptr = gsl.gsl_matrix_complex_alloc(size1, size2)
        self.size1 = size1
        self.size2 = size2

    def __del__(self):
        if hasattr(self, '_ptr'):
            gsl.gsl_matrix_complex_free(self._ptr)
            del self._ptr

    def to_np(self):
        """Convert gsl_matrix_complex to a NumPy array."""
        data = []
        for i in range(self.size1):
            row = []
            for j in range(self.size2):
                z = gsl.gsl_matrix_complex_get(self._ptr, i, j)
                row.append(complex(z.dat[0], z.dat[1]))
            data.append(row)
        return np.array(data)

    @staticmethod
    def from_np(np_array):
        """Convert a NumPy array to a gsl_matrix_complex."""
        size1, size2 = np_array.shape
        gsl_mat = gsl_matrix_complex(size1, size2)
        for i in range(size1):
            for j in range(size2):
                gsl.gsl_matrix_complex_set(gsl_mat._ptr, i, j, gsl.gsl_complex_rect(np_array[i, j].real, np_array[i, j].imag))
        return gsl_mat


