        gsl = ctypes.CDLL(os.path.join('/usr/local', 'gsl', 'lib', 'libgsl.so'))

        # Define necessary GSL types and functions
        interp_types = {
            'linear': gsl.gsl_interp_linear,
            'polynomial': gsl.gsl_interp_polynomial,
            'cspline': gsl.gsl_interp_cspline,
            'cspline_periodic': gsl.gsl_interp_cspline_periodic,
            'akima': gsl.gsl_interp_akima,
            'akima_periodic': gsl.gsl_interp_akima_periodic
        }

