        if not os.path.exists(libgsl_path):
            raise FileNotFoundError(f"libgsl.so not found at: {libgsl_path}")
        if not os.path.exists(libgslcblas_path):
            raise FileNotFoundError(f"libgslcblas.so not found at: {libgslcblas_path}")

        try:
            ctypes.CDLL(libgslcblas_path, mode=ctypes.RTLD_GLOBAL)
            self.libgsl = ctypes.CDLL(libgsl_path)
        except OSError as e:
