        self.libgsl.gsl_rng_alloc.restype = ctypes.c_void_p
        self.libgsl.gsl_rng_set.argtypes = [ctypes.c_void_p, ctypes.c_ulong]
        self.libgsl.gsl_rng_get.restype = ctypes.c_ulong
        self.libgsl.gsl_rng_free.argtypes = [ctypes.c_void_p]
        self.rng = None

    def __enter__(self):
        self.rng = self.libgsl.gsl_rng_alloc(ctypes.c_void_p.in_dll(self.libgsl, "gsl_rng_ranlux"))
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.rng:
            self.libgsl.gsl_rng_free(self.rng)

    def set_seed(self, seed):
        if not self.rng:
            raise ValueError("Random number generator not initialized.")
        self.libgsl.gsl_rng_set(self.rng, seed)

    def get_double(self):
        if not self.rng:
            raise ValueError("Random number generator not initialized.")
        self.libgsl.gsl_rng_get_double.restype = ctypes.c_double  # Ensure correct return type
        self.libgsl.gsl_rng_get_double.argtypes = [ctypes.c_void_p]
