def gsl_ldexp_py(x, e):
    try:
        # Load GSL libraries in the correct order
        # First try the standard locations
        try:
            ctypes.CDLL("libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
            gsl = ctypes.CDLL("libgsl.so")
