import os

def set_ieee_mode(precision, rounding, exception_mask):
    try:
        # Load GSL libraries in the correct order
        # First try to load from standard locations
        try:
            ctypes.CDLL("libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
            gsl = ctypes.CDLL("libgsl.so")
        except OSError:
            # If not found, try user-specified location
            if "GSL_LIB_PATH" in os.environ:
                gsl_lib_path = os.environ["GSL_LIB_PATH"]
                ctypes.CDLL(os.path.join(gsl_lib_path, "libgslcblas.so"), mode=ctypes.RTLD_GLOBAL)
                gsl = ctypes.CDLL(os.path.join(gsl_lib_path, "libgsl.so"))
            else:
                raise OSError("GSL libraries not found. Please set GSL_LIB_PATH environment variable.")

        # Define argument and return types
        gsl.gsl_ieee_set_mode.argtypes = [ctypes.c_int, ctypes.c_int, ctypes.c_int]
        gsl.gsl_ieee_set_mode.restype = ctypes.c_int

        # Define constants for precision, rounding, and exception mask
        GSL_PREC_SINGLE = 0
        GSL_PREC_DOUBLE = 1
        GSL_PREC_APPROX = 2

        GSL_ROUND_TO_NEAREST = 0
        GSL_ROUND_DOWN = 1
        GSL_ROUND_UP = 2
        GSL_ROUND_TO_ZERO = 3

        GSL_IEEE_MASK_ALL = 0
        GSL_IEEE_MASK_INVALID = 1
        GSL_IEEE_MASK_DENORMALIZED = 2
        GSL_IEEE_MASK_DIVISION_BY_ZERO = 4
        GSL_IEEE_MASK_OVERFLOW = 8
        GSL_IEEE_MASK_UNDERFLOW = 16
        GSL_IEEE_MASK_INEXACT = 32

        # Map input strings to GSL constants
        precision_mapping = {"single": GSL_PREC_SINGLE, "double": GSL_PREC_DOUBLE, "approx": GSL_PREC_APPROX}
        rounding_mapping = {"nearest": GSL_ROUND_TO_NEAREST, "down": GSL_ROUND_DOWN, "up": GSL_ROUND_UP, "zero": GSL_ROUND_TO_ZERO}
        exception_mask_mapping = {"all": GSL_IEEE_MASK_ALL, "invalid": GSL_IEEE_MASK_INVALID, "denormalized": GSL_IEEE_MASK_DENORMALIZED, "division_by_zero": GSL_IEEE_MASK_DIVISION_BY_ZERO, "overflow": GSL_IEEE_MASK_OVERFLOW, "underflow": GSL_IEEE_MASK_UNDERFLOW, "inexact": GSL_IEEE_MASK_INEXACT}

        # Validate input and convert to GSL constants
        if precision not in precision_mapping:
            raise ValueError("Invalid precision value.")
        if rounding not in rounding_mapping:
            raise ValueError("Invalid rounding value.")
        if exception_mask not in exception_mask_mapping:
            raise ValueError("Invalid exception mask value.")

        precision_value = precision_mapping[precision]
        rounding_value = rounding_mapping[rounding]
        exception_mask_value = exception_mask_mapping[exception_mask]

        # Call GSL function
        result = gsl.gsl_ieee_set_mode(precision_value, rounding_value, exception_mask_value)

        return result

    except OSError as e:
        return str(e)
    except ValueError as e:
        return str(e)
    except Exception as e:
        return "An unexpected error occurred: " + str(e)

