class GSLFunction:
    def __init__(self, f):
        self.f = f
        self.callback_type = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)
        self.callback = self.callback_type(self.callback)

    def callback(self, x):
        return self.f(x)

class GSLIntegrationWorkspace:
    def __init__(self, limit):
        self.w = gsl.gsl_integration_workspace_alloc(limit)

    def __del__(self):
        gsl.gsl_integration_workspace_free(self.w)

def integrate(function, a, b, epsabs, epsrel, limit, key):
    gsl_function = GSLFunction(function)
    workspace = GSLIntegrationWorkspace(limit)

    result = ctypes.c_double(0.0)
    error = ctypes.c_double(0.0)

    gsl.gsl_integration_qag.argtypes = [
        gsl_function.callback_type, ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.c_int, ctypes.c_int, ctypes.POINTER(ctypes.c_void_p), ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double)
