    status = gsl.gsl_integration_qag(
        gsl_function.callback, a, b, epsabs, epsrel, limit, key, workspace.w, ctypes.byref(result), ctypes.byref(error)
    )

    if status != 0:
        raise RuntimeError(f"GSL integration failed with status {status}")

    return result.value, error.value


