import os

class GSLBlock(ctypes.Structure):
    _fields_ = [("size", ctypes.c_size_t), ("data", ctypes.POINTER(ctypes.c_double))]

class GSLVector(ctypes.Structure):
    _fields_ = [("size", ctypes.c_size_t), ("stride", ctypes.c_size_t), ("data", ctypes.POINTER(ctypes.c_double)), ("block", ctypes.POINTER(GSLBlock)), ("owner", ctypes.c_int)]

class GSLMatrix(ctypes.Structure):
    _fields_ = [("size1", ctypes.c_size_t), ("size2", ctypes.c_size_t), ("tda", ctypes.c_size_t), ("data", ctypes.POINTER(ctypes.c_double)), ("block", ctypes.POINTER(GSLBlock)), ("owner", ctypes.c_int)]

class GSLVectorView(ctypes.Structure):
    _fields_ = [("vector", GSLVector)]

def extract_row(matrix, row_index):
    try:
        # Load GSL libraries in the specified order
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        # Define the function prototype
        gsl_matrix_row = gsl.gsl_matrix_row
        gsl_matrix_row.restype = ctypes.POINTER(GSLVectorView)
        gsl_matrix_row.argtypes = [ctypes.POINTER(GSLMatrix), ctypes.c_size_t]

        # Check if the libraries loaded correctly and the function exists
        if not gsl or not gsl_matrix_row:
            raise OSError("Could not load GSL libraries or find gsl_matrix_row function.")

        # Check if row_index is valid
        if row_index < 0 or row_index >= matrix.contents.size1:
            raise IndexError("Row index out of bounds.")

        # Call the GSL function
        row_view = gsl_matrix_row(ctypes.byref(matrix), row_index)

        # Check if the row extraction was successful
        if not row_view:
            raise RuntimeError("Failed to extract row from matrix.")

        return row_view.contents.vector

    except OSError as e:
        print(f"Error loading GSL libraries: {e}")
        return None
    except IndexError as e:
        print(f"Error: {e}")
        return None
    except RuntimeError as e:
        print(f"Error extracting row: {e}")
        return None
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return None

