    gsl = ctypes.CDLL(os.path.join('/usr/local', 'gsl', 'lib', 'libgsl.so'))

    # Define the cblas_sasum function
    cblas_sasum = gsl.cblas_sasum
    cblas_sasum.argtypes = [ctypes.c_int, ctypes.POINTER(ctypes.c_float), ctypes.c_int]
    cblas_sasum.restype = ctypes.c_float

    def sasum(N, X, incX):
        """Computes the sum of the absolute values of elements in a float array."""
        if not isinstance(N, int):
            raise TypeError("N must be an integer.")
        if not isinstance(X, list):
            raise TypeError("X must be a list.")
        if not all(isinstance(x, float) for x in X):
            raise TypeError("Elements of X must be floats.")
        if not isinstance(incX, int):
            raise TypeError("incX must be an integer.")

        if N < 0:
            raise ValueError("N must be non-negative.")
        if incX < 0:
            raise ValueError("incX must be non-negative.")

        # Convert the list X to a ctypes array
        x_array = (ctypes.c_float * len(X))(*X)

        # Call the cblas_sasum function
        result = cblas_sasum(N, x_array, incX)

        return result

except OSError as e:
