import numpy as np

class GSLHistogram2D:
    def __init__(self, nx, ny, xrange, yrange, bin_data=None):
        self.nx = nx
        self.ny = ny
        self.xrange = xrange
        self.yrange = yrange

        # Load GSL libraries
        try:
            ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
            self.gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        except OSError as e:
            print(f"Error loading GSL libraries: {e}")
            raise

        # Initialize the histogram
        self.histogram = self.gsl.gsl_histogram2d_alloc(self.nx, self.ny)
        if self.histogram is None:
            raise MemoryError("Failed to allocate histogram")

        self.gsl.gsl_histogram2d_set_ranges_uniform(self.histogram, self.xrange[0], self.xrange[1], self.yrange[0], self.yrange[1])

        if bin_data is not None:
            for i in range(nx):
                for j in range(ny):
                    self.gsl.gsl_histogram2d_set_bin(self.histogram, i, j, bin_data[i][j])

    def clone(self):
        cloned_histogram = self.gsl.gsl_histogram2d_clone(self.histogram)
        if cloned_histogram is None:
            raise MemoryError("Failed to clone histogram")

        # Wrap the cloned histogram in a new GSLHistogram2D object
        cloned_bin_data = np.zeros((self.nx, self.ny), dtype=float)
        for i in range(self.nx):
            for j in range(self.ny):
                cloned_bin_data[i, j] = self.gsl.gsl_histogram2d_get(cloned_histogram, i, j)

        cloned_obj = GSLHistogram2D(self.nx, self.ny, self.xrange, self.yrange, cloned_bin_data)
        cloned_obj.histogram = cloned_histogram  # Replace the allocated histogram with the cloned one
        return cloned_obj

def create_histogram(nx, ny, xrange, yrange, bin_data):
    return GSLHistogram2D(nx, ny, xrange, yrange, bin_data)

