import ctypes
import os

class gsl_block_struct(ctypes.Structure):
    _fields_ = [('size', ctypes.c_size_t), ('data', ctypes.POINTER(ctypes.c_double))]

class gsl_matrix(ctypes.Structure):
    _fields_ = [('size1', ctypes.c_size_t), ('size2', ctypes.c_size_t), ('tda', ctypes.c_size_t),
                ('data', ctypes.POINTER(ctypes.c_double)), ('block', ctypes.POINTER(gsl_block_struct)),
                ('owner', ctypes.c_int)]

class gsl_vector(ctypes.Structure):
    _fields_ = [('size', ctypes.c_size_t), ('stride', ctypes.c_size_t),
                ('data', ctypes.POINTER(ctypes.c_double)), ('block', ctypes.POINTER(gsl_block_struct)),
                ('owner', ctypes.c_int)]

def extract_row_from_matrix(matrix, vector, row_index):
    try:
        # Load GSL libraries in the correct order
        try:
            ctypes.CDLL(os.path.join("usr", "local", "gsl", "lib", "libgslcblas.so"), mode=ctypes.RTLD_GLOBAL)
            gsl = ctypes.CDLL(os.path.join("usr", "local", "gsl", "lib", "libgsl.so"))
        except OSError as e:
            # Check if GSL is installed in /usr/lib64/
            try:
                ctypes.CDLL(os.path.join("usr", "lib64", "libgslcblas.so"), mode=ctypes.RTLD_GLOBAL)
                gsl = ctypes.CDLL(os.path.join("usr", "lib64", "libgsl.so"))
            except OSError as e2:
                raise Exception("Failed to load GSL libraries from both /usr/local/gsl/lib and /usr/lib64. " + str(e) + " " + str(e2)) from e

        gsl_matrix_get_row = gsl.gsl_matrix_get_row
        gsl_matrix_get_row.argtypes = [ctypes.POINTER(gsl_matrix), ctypes.c_size_t, ctypes.POINTER(gsl_vector)]
        gsl_matrix_get_row.restype = ctypes.c_int

        status = gsl_matrix_get_row(ctypes.byref(matrix), row_index, ctypes.byref(vector))

        if status != 0:
            raise Exception(f"gsl_matrix_get_row failed with status code: {status}")

        return 0

    except Exception as e:
        raise Exception("Error extracting row from matrix: " + str(e)) from e

