import os

def compute_gegenpoly(n: int, lambda_val: float, x: float) -> float:
    try:
        # Load GSL libraries
        libgslcblas_path = os.path.join('/usr/local', 'gsl', 'lib', 'libgslcblas.so')
        libgsl_path = os.path.join('/usr/local', 'gsl', 'lib', 'libgsl.so')

        if os.path.exists(libgslcblas_path):
            ctypes.CDLL(libgslcblas_path, mode=ctypes.RTLD_GLOBAL)
        if os.path.exists(libgsl_path):
            gsl = ctypes.CDLL(libgsl_path)
        else:
            raise OSError("libgsl.so not found. Please install GSL and ensure that LD_LIBRARY_PATH is set correctly.")

        # Define necessary C types
        gsl.gsl_sf_gegenpoly_n_e.restype = ctypes.c_double
        gsl.gsl_sf_gegenpoly_n_e.argtypes = [ctypes.c_int, ctypes.c_double, ctypes.c_double]

        # Define GSL error handling
        class gsl_sf_result(ctypes.Structure):
            _fields_ = [
                ('val', ctypes.c_double),
                ('err', ctypes.c_double),
            ]

        # Initialize result structure
        result = gsl_sf_result()

        # Call GSL function
        status = gsl.gsl_sf_gegenpoly_n_e(n, lambda_val, x, ctypes.byref(result))

        # Check for errors
        if status != 0:
            raise ValueError(f"GSL function returned error code: {status}")

        return result.val

    except OSError as e:
        print(f"Error loading GSL library: {e}")
        return float('nan')
    except ValueError as e:
        print(f"Error computing Gegenbauer polynomial: {e}")
        return float('nan')
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return float('nan')

