        ORDER = {
            'CblasRowMajor': 101,
            'CblasColMajor': 102
        }
        SIDE = {
            'CblasLeft': 141,
            'CblasRight': 142
        }
        UPLO = {
            'CblasUpper': 121,
            'CblasLower': 122
        }

        # Convert input parameters to appropriate ctypes
        order = ctypes.c_int(ORDER.get(order_int, order_int))
