class GSLVector:
    def __init__(self, size):
        self.size = size
        self.data = (ctypes.c_double * size)()  # Initialize with zeros

    def set_data(self, data_list):
        if len(data_list) != self.size:
            raise ValueError("Data list size does not match vector size.")
        for i, value in enumerate(data_list):
            self.data[i] = value

    def get_data_as_list(self):
        return [self.data[i] for i in range(self.size)]

class GSLVectorView:
    def __init__(self, vector, start, length):
        self.vector = vector
        self.start = start
        self.length = length
