import os

class GSLResult:
    def __init__(self, value, error):
        self.value = value
        self.error = error

def compute_bessel_Jn(n, x):
    try:
        n = int(n)
        x = float(x)
    except (ValueError, TypeError):
        return GSLResult(None, "Invalid input: n must be an integer, x must be a float.")

    try:
        # Load GSL libraries in the correct order
        libgslcblas_path = os.path.join('/usr/local', 'gsl', 'lib', 'libgslcblas.so')
        libgsl_path = os.path.join('/usr/local', 'gsl', 'lib', 'libgsl.so')

        if os.path.exists(libgslcblas_path):
            ctypes.CDLL(libgslcblas_path, mode=ctypes.RTLD_GLOBAL)
        else:
            return GSLResult(None, f"libgslcblas.so not found at {libgslcblas_path}")

        if os.path.exists(libgsl_path):
            gsl = ctypes.CDLL(libgsl_path)
        else:
            return GSLResult(None, f"libgsl.so not found at {libgsl_path}")

        gsl.gsl_sf_bessel_Jn_e.restype = ctypes.c_int
        gsl.gsl_sf_bessel_Jn_e.argtypes = [ctypes.c_int, ctypes.c_double, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double)]

        result = ctypes.c_double(0.0)
        error = ctypes.c_double(0.0)

