        data = np.ascontiguousarray(data)

    if data.dtype == np.complex64:
        gsl_fft_complex_radix2_forward = gsl.gsl_fft_complex_radix2_forward
        gsl_fft_complex_radix2_forward.argtypes = [ctypes.POINTER(ctypes.c_float), ctypes.c_size_t, ctypes.c_size_t]
