    if status != 0:
        raise RuntimeError("GSL FFT failed with status {}".format(status))

    # Convert back to NumPy array
    if data.dtype == np.complex64:
        transformed_data = np.frombuffer(data_ctypes, dtype=np.float32).reshape((2*data.size,))
        transformed_data = transformed_data[:data.size] + 1j * transformed_data[data.size:]
