def permute_vector(input_vector, permutation):
    try:
        # Load GSL libraries in the correct order
        ctypes.CDLL(os.path.join('/usr','local','gsl','lib','libgslcblas.so'), mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL(os.path.join('/usr','local','gsl','lib', 'libgsl.so'))

        # Define the function signature
        gsl.gsl_permute.argtypes = [ctypes.POINTER(ctypes.c_size_t), ctypes.POINTER(ctypes.c_double), ctypes.c_size_t]
        gsl.gsl_permute.restype = ctypes.c_int

        # Convert input lists to appropriate ctypes
        n = len(input_vector)
        p = (ctypes.c_size_t * n)(*permutation)
        v = (ctypes.c_double * n)(*input_vector)

        # Call the GSL function
        status = gsl.gsl_permute(p, v, n)

        if status != 0:
            raise Exception("GSL function gsl_permute failed with status code {}".format(status))

