import ctypes

class GSLVector:
    def __init__(self, size):
        self._size = size
        self._data = (ctypes.c_double * 2 * self._size)()

    def size(self):
        return self._size

    def get_data(self):
        return self._data

    @staticmethod
    def from_list(data_list):
        size = len(data_list)
        vec = GSLVector(size)
        for i, (real, imag) in enumerate(data_list):
            vec._data[2 * i] = real
            vec._data[2 * i + 1] = imag
        return vec

def vector_conj_memcpy(dest, src):
    if not isinstance(dest, GSLVector) or not isinstance(src, GSLVector):
        raise TypeError("Both dest and src must be GSLVector objects.")

    if dest.size() != src.size():
        raise ValueError("Source and destination vectors must have the same size.")

    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        gsl.gsl_vector_complex_conj_memcpy.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.c_size_t]
        gsl.gsl_vector_complex_conj_memcpy.restype = ctypes.c_int

        status = gsl.gsl_vector_complex_conj_memcpy(dest.get_data(), src.get_data(), dest.size())
        return status

    except OSError as e:
        print(f"Error loading GSL libraries: {e}")
        return -1

