import ctypes
import os

class GSLBlock:
    def __init__(self, libgsl_path="/usr/local/gsl/lib/libgsl.so", libgslcblas_path="/usr/local/gsl/lib/libgslcblas.so"):
        try:
            # Load GSL libraries respecting the order
            if os.path.exists(libgslcblas_path):
                ctypes.CDLL(libgslcblas_path, mode=ctypes.RTLD_GLOBAL)
            self.libgsl = ctypes.CDLL(libgsl_path)

            # Define argument and return types for GSL functions
            self.libgsl.gsl_block_alloc.argtypes = [ctypes.c_size_t]
            self.libgsl.gsl_block_alloc.restype = ctypes.c_void_p
            self.libgsl.gsl_block_calloc.argtypes = [ctypes.c_size_t]
            self.libgsl.gsl_block_calloc.restype = ctypes.c_void_p
            self.libgsl.gsl_block_free.argtypes = [ctypes.c_void_p]
            self.libgsl.gsl_block_free.restype = None
            self.gsl_loaded = True
        except OSError:
            self.gsl_loaded = False

    def allocate_and_free_block(self, n):
        if not self.gsl_loaded:
            return False

        try:
            # Allocate a block
            block = self.libgsl.gsl_block_calloc(n)
            if not block:
                return False  # Allocation failed

            # Free the block
            self.libgsl.gsl_block_free(block)
            return True
        except Exception:
            return False

