import ctypes
import os

def compute_integral(py_func, a, b, epsabs, epsrel, n):
    # Load GSL libraries
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError:
        return {"error": "Could not load GSL libraries. Check if they are installed and accessible."}

    # Define C function types
    gsl.gsl_integration_romberg_alloc.restype = ctypes.c_void_p
    gsl.gsl_integration_romberg_alloc.argtypes = [ctypes.c_size_t]
    gsl.gsl_integration_romberg.restype = ctypes.c_int
    gsl.gsl_integration_romberg.argtypes = [ctypes.POINTER(gsl_function), ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_size_t), ctypes.c_void_p]
    gsl.gsl_integration_romberg_free.argtypes = [ctypes.c_void_p]

    # Create GSL function struct
    class gsl_function(ctypes.Structure):
        _fields_ = [("function", ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.c_void_p)),
                    ("params", ctypes.c_void_p)]

    # Wrap Python function
    def func_wrapper(x, params):
        return py_func(x)

    c_func = gsl_function(ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.c_void_p)(func_wrapper), None)

    # Allocate workspace
    w = gsl.gsl_integration_romberg_alloc(n)
    if not w:
        return {"error": "Failed to allocate workspace."}

    # Perform integration
    result = ctypes.c_double(0.0)
    eval_count = ctypes.c_size_t(0)
    status = gsl.gsl_integration_romberg(ctypes.byref(c_func), a, b, epsabs, epsrel, ctypes.byref(result), ctypes.byref(eval_count), w)

    # Free workspace
    gsl.gsl_integration_romberg_free(w)

    if status != 0:
        return {"error": f"GSL integration failed with status {status}."}

    return {"result": result.value, "evaluations": eval_count.value}

