            self.gsl.gsl_rng_alloc.restype = ctypes.c_void_p
            self.gsl.gsl_rng_alloc.argtypes = [ctypes.c_void_p]
            self.gsl.gsl_rng_set.argtypes = [ctypes.c_void_p, ctypes.c_ulong]
            self.gsl.gsl_rng_free.argtypes = [ctypes.c_void_p]
            self.gsl.gsl_rng_get.restype = ctypes.c_ulong
            self.gsl.gsl_rng_get.argtypes = [ctypes.c_void_p]
