            # Initialize the RNG
            self.T = self.gsl.gsl_rng_alloc(self.gsl.gsl_rng_taus)
            if not self.T:
                raise RuntimeError("Failed to allocate RNG")
        except OSError as e:
            raise RuntimeError(f"Failed to load GSL libraries: {e}")

    def generate_random(self, seed):
        try:
            self.gsl.gsl_rng_set(self.T, seed)
            random_number = self.gsl.gsl_rng_uniform(self.T)
            return random_number
        except Exception as e:
            raise RuntimeError(f"Failed to generate random number: {e}")

    def __del__(self):
        if hasattr(self, 'T') and self.T:
            self.gsl.gsl_rng_free(self.T)

