def compute_clausen(x):
    try:
        # Load GSL libraries
        try:
            ctypes.CDLL(os.path.join('/usr/local/gsl/lib/', 'libgslcblas.so'), mode=ctypes.RTLD_GLOBAL)
            gsl = ctypes.CDLL(os.path.join('/usr/local/gsl/lib/', 'libgsl.so'))
        except OSError as e:
            # Check if the libraries exist in /usr/lib
            try:
                ctypes.CDLL(os.path.join('/usr/lib/', 'libgslcblas.so'), mode=ctypes.RTLD_GLOBAL)
                gsl = ctypes.CDLL(os.path.join('/usr/lib/', 'libgsl.so'))
            except OSError as e:
                return {"error": str(e)}

        # Define the function prototype
        gsl_sf_clausen = gsl.gsl_sf_clausen
        gsl_sf_clausen.restype = ctypes.c_double
        gsl_sf_clausen.argtypes = [ctypes.c_double]

        # Compute the Clausen function value
        result = gsl_sf_clausen(x)

        return result

    except Exception as e:
        return {"error": str(e)}

